/**
 * Conformance audit against structures produced by OpenSSL.
 *
 * `test-fixtures/openssl-corpus/corpus.ts` holds ~220 valid DER files generated by OpenSSL 3
 * (see `generate.sh` there). For every file we check that pki-lite can parse it and
 * that re-encoding the parsed object gives back the original bytes, plus a handful of
 * semantic checks (verify a signature, decrypt, extract PKCS#12 items, ...).
 *
 * Cases that currently fail because of a real pki-lite defect are registered in
 * `KNOWN_ISSUES` and run with `test.fails`: CI stays green, and as soon as a defect is
 * fixed the matching tests start failing with "expected to fail", pointing at the entry
 * to delete.
 */
import { describe, expect, test } from 'vitest'
import { opensslCorpus } from '../../test-fixtures/openssl-corpus/corpus.js'
import { Certificate } from '../../src/x509/Certificate.js'
import { CertificateRequest } from '../../src/x509/CertificateRequest.js'
import { CertificateList } from '../../src/x509/CertificateList.js'
import { BasicConstraints } from '../../src/x509/extensions/BasicConstraints.js'
import { KeyUsage } from '../../src/x509/extensions/KeyUsage.js'
import { ExtKeyUsage } from '../../src/x509/extensions/ExtKeyUsage.js'
import { SubjectAltName } from '../../src/x509/extensions/SubjectAltName.js'
import { AuthorityKeyIdentifier } from '../../src/x509/extensions/AuthorityKeyIdentifier.js'
import { CRLDistributionPoints } from '../../src/x509/extensions/CRLDistributionPoints.js'
import { AuthorityInfoAccess } from '../../src/x509/extensions/AuthorityInfoAccess.js'
import { NameConstraints } from '../../src/x509/extensions/NameConstraints.js'
import { SubjectKeyIdentifier } from '../../src/keys/SubjectKeyIdentifier.js'
import { PrivateKeyInfo } from '../../src/keys/PrivateKeyInfo.js'
import { SubjectPublicKeyInfo } from '../../src/keys/SubjectPublicKeyInfo.js'
import { RSAPrivateKey } from '../../src/keys/RSAPrivateKey.js'
import { RSAPublicKey } from '../../src/keys/RSAPublicKey.js'
import { ECPrivateKey } from '../../src/keys/ECPrivateKey.js'
import { ECDSASignature } from '../../src/keys/ECDSASignature.js'
import { EncryptedPrivateKeyInfo } from '../../src/keys/EncryptedPrivateKeyInfo.js'
import { ContentInfo } from '../../src/pkcs7/ContentInfo.js'
import { SignedData } from '../../src/pkcs7/SignedData.js'
import { EnvelopedData } from '../../src/pkcs7/EnvelopedData.js'
import { PFX } from '../../src/pkcs12/PFX.js'
import { OCSPRequest } from '../../src/ocsp/OCSPRequest.js'
import { OCSPResponse } from '../../src/ocsp/OCSPResponse.js'

// Only browser-safe APIs here (atob, TextDecoder, ...): this file runs in both the
// node and the browser vitest projects.
const read = (family: string, file: string): Uint8Array<ArrayBuffer> =>
    Uint8Array.from(atob(opensslCorpus[family][file]), (c) => c.charCodeAt(0))
const files = (family: string) => Object.keys(opensslCorpus[family]).sort()
const hex = (b: Uint8Array) =>
    Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')

/** The message signed / encrypted by the CMS fixtures (generate/04-*.sh). */
const CMS_MESSAGE = 'Hello, CMS world\n'

// ---------------------------------------------------------------------------
// Known defects. `match` is tested against "<family>/<file>" and the check name.
// ---------------------------------------------------------------------------
type KnownIssue = {
    id: string
    why: string
    match: (target: string, check: string) => boolean
}

const KNOWN_ISSUES: KnownIssue[] = [
    {
        id: 'GENERALNAME-EXPLICIT-TAGS',
        why:
            'GeneralName choices that are IMPLICIT in RFC 5280 (rfc822Name, dNSName, URI, ...) are ' +
            'encoded as an explicit constructed [n] wrapping an IA5String (A2 0F 16 0D ...) instead of ' +
            'a primitive [n] (82 0D ...). OpenSSL tolerates it as a BER constructed string; DER parsers do not. ' +
            'Affects every extension that embeds a GeneralName.',
        // directoryName ([4] Name) is a CHOICE, so EXPLICIT is correct for it
        match: (t, c) =>
            !/san1_dirname/.test(t) &&
            /^ext:(subjectAltName|issuerAltName|authorityInfoAccess|subjectInfoAccess|crlDistributionPoints|freshestCRL):roundtrip$/.test(
                c,
            ),
    },
    {
        id: 'AKI-KEYIDENTIFIER-EXPLICIT-TAG',
        why: 'AuthorityKeyIdentifier writes keyIdentifier [0] as an explicit wrapper (A0 16 04 14 ...) instead of IMPLICIT (80 14 ...).',
        match: (_t, c) => c === 'ext:authorityKeyIdentifier:roundtrip',
    },
    {
        id: 'AKI-AUTHORITYCERTISSUER-PARSE',
        why: 'AuthorityKeyIdentifier cannot parse authorityCertIssuer [1] (GeneralNames is implicit, so the content is the GeneralName elements, not a SEQUENCE).',
        match: (t, c) =>
            c === 'ext:authorityKeyIdentifier:parse' &&
            /akid_(issuer_only|keyid_issuer)/.test(t),
    },
    {
        id: 'KEYUSAGE-NOT-MINIMAL-DER',
        why: 'KeyUsage always encodes a two-byte BIT STRING; DER requires trailing zero bits of a named bit list to be dropped (03 02 07 80, not 03 03 07 80 00).',
        match: (t, c) =>
            c === 'ext:keyUsage:roundtrip' && !/decipherOnly/.test(t),
    },
    {
        id: 'CRLDP-PARSE',
        why: 'CRLDistributionPoints cannot parse a DistributionPoint with reasons / cRLIssuer / relativeName.',
        match: (t, c) =>
            c === 'ext:crlDistributionPoints:parse' && /dp_full/.test(t),
    },
    {
        id: 'SAN-OTHERNAME-AND-RID-PARSE',
        why: 'SubjectAltName cannot parse an otherName or a registeredID (the implicit [0]/[8] forms are mishandled), so the whole extension fails.',
        match: (t, c) =>
            /^ext:(subjectAltName|issuerAltName):parse$|^accessors$/.test(c) &&
            /san_all|san1_othername|san1_rid/.test(t),
    },
    {
        id: 'NAMECONSTRAINTS-NO-PARSER',
        why: 'NameConstraints has no fromAsn1/fromDer, so it cannot be parsed from a certificate.',
        match: (_t, c) => /^ext:nameConstraints:(parse|roundtrip)$/.test(c),
    },
    {
        id: 'SIGNATURE-ALGORITHMS-UNSUPPORTED',
        why: 'isSelfSigned/verify does not support Ed25519, Ed448 or RSA-PSS keys.',
        match: (t, c) =>
            (c === 'isSelfSigned' &&
                /key_ed25519|key_ed448|key_rsapss/.test(t)) ||
            (c === 'signedData:verify' && /sd_ed25519/.test(t)),
    },
    {
        id: 'CSR-ATTRIBUTES-PARSE',
        why:
            'CertificateRequestInfo cannot parse the [0] attributes field: it crashes on the empty `A0 00` ' +
            'OpenSSL writes for a request without attributes, and for non-empty attributes it expects an ' +
            'explicit SET wrapper that PKCS#10 (IMPLICIT SET OF) does not have. No OpenSSL-made CSR can be read.',
        match: (t, c) => t.startsWith('csr/') && /^(parse|roundtrip)$/.test(c),
    },
    {
        id: 'CRL-GENERALIZEDTIME-ROUNDTRIP',
        why: 'A CRL whose thisUpdate/nextUpdate are GeneralizedTime (year >= 2050) is re-encoded differently.',
        match: (t, c) => c === 'roundtrip' && t === 'crl/crl_gentime.der',
    },
    {
        id: 'ECPRIVATEKEY-EXPLICIT-PARAMS',
        why: 'ECPrivateKey cannot parse explicit (non-namedCurve) EC parameters.',
        match: (t, c) =>
            /^(parse|roundtrip)$/.test(c) &&
            t === 'key/ecprivate_explicitparams.der',
    },
    {
        id: 'SIGNERIDENTIFIER-SKI',
        why: 'A SignerInfo/KeyTransRecipientInfo identified by subjectKeyIdentifier ([0] IMPLICIT) cannot be parsed.',
        match: (t, c) =>
            /^(signedData|envelopedData):(parse|roundtrip|decrypt)$/.test(c) &&
            /sd_keyid|ed_rsa_keyid/.test(t),
    },
    {
        id: 'RECIPIENTINFO-KARI-KEKRI-PWRI',
        why: 'EnvelopedData cannot parse KeyAgreeRecipientInfo, KEKRecipientInfo or PasswordRecipientInfo (implicitly tagged choices expected to be plain SEQUENCEs).',
        match: (t, c) =>
            /^envelopedData:(parse|roundtrip)$/.test(c) &&
            /ed_ec_kari|ed_multi|ed_kekri|ed_pwri/.test(t),
    },
    {
        id: 'CMS-RSA-SIGNERINFO-ALGORITHM',
        why: 'SignerInfo.signatureAlgorithm = rsaEncryption (what OpenSSL writes for RSA PKCS#1 v1.5) is rejected with "Unsupported algorithm: RSA", so plain RSA CMS signatures cannot be verified.',
        match: (t, c) =>
            c === 'signedData:verify' &&
            /sd_(big|certfile_chain|detached_rsa|attached_rsa|noattr|nosmimecap|econtent_type|keyid|sha512|empty_content)/.test(
                t,
            ),
    },
    {
        id: 'AUTHENVELOPEDDATA-MISPARSED',
        why:
            'AuthEnvelopedData (1.2.840.113549.1.9.16.1.23, what `openssl cms -encrypt -aes-256-gcm` writes) is ' +
            'accepted as EnvelopedData without checking the content type; it is re-encoded under the EnvelopedData ' +
            'OID and the authentication tag/attributes are dropped, and decryption fails.',
        match: (t, c) =>
            /^envelopedData:(roundtrip|decrypt)$/.test(c) &&
            /ed_rsa_gcm|authenveloped/.test(t),
    },
    {
        id: 'CMS-BER-INDEFINITE-LENGTH',
        why: 'Indefinite-length / constructed-OCTET-STRING BER (openssl cms -stream) is not handled: the eContent digest is computed over the wrong bytes.',
        match: (t, c) =>
            /_stream/.test(t) && /verify|decrypt|roundtrip/.test(c),
    },
    {
        id: 'CMS-RSA-PKCS1V15-KEY-TRANSPORT',
        why: 'EnvelopedData.decrypt cannot unwrap RSA PKCS#1 v1.5 key transport (rsaEncryption), the OpenSSL default.',
        match: (t, c) =>
            c === 'envelopedData:decrypt' &&
            /ed_rsa_(3des|aes128|aes256)|ed_stream|ed_empty/.test(t),
    },
    {
        id: 'OCSP-REVOKED-PARSE',
        why: 'CertStatus.fromAsn1 crashes (reading "toDate" of undefined) on every `revoked` status, so a response for a revoked certificate cannot be parsed.',
        match: (t, c) =>
            c === 'basic:parse' &&
            /resp_(revoked|nonce|multi|nextupdate|ndays|keyid)/.test(t),
    },
    {
        id: 'PKCS12-3DES-UNSUPPORTED',
        why: 'PKCS#12 pbeWithSHAAnd3-KeyTripleDES-CBC is not supported.',
        match: (t, c) => c === 'extractItems' && t === 'p12/legacy_3des.p12',
    },
    {
        id: 'PKCS12-PLAIN-KEYBAG',
        why: 'An unencrypted keyBag (openssl pkcs12 -keypbe NONE) is not returned by getPrivateKeys.',
        match: (t, c) => c === 'extractItems' && t === 'p12/keypbe_none.p12',
    },
]

function register(
    family: string,
    file: string,
    check: string,
    fn: () => void | Promise<void>,
) {
    const target = `${family}/${file}`
    const known = KNOWN_ISSUES.find((k) => k.match(target, check))
    const name = `${file} :: ${check}`
    if (known) {
        test.fails(`${name} [known issue: ${known.id}]`, fn)
    } else {
        test(name, fn)
    }
}

function expectRoundtrip(obj: { toDer(): Uint8Array }, der: Uint8Array) {
    expect(hex(obj.toDer())).toBe(hex(der))
}

// ---------------------------------------------------------------------------
// Certificates
// ---------------------------------------------------------------------------
const EXTENSIONS: Record<string, [string, any]> = {
    '2.5.29.19': ['basicConstraints', BasicConstraints],
    '2.5.29.15': ['keyUsage', KeyUsage],
    '2.5.29.37': ['extKeyUsage', ExtKeyUsage],
    '2.5.29.17': ['subjectAltName', SubjectAltName],
    '2.5.29.18': ['issuerAltName', SubjectAltName],
    '2.5.29.35': ['authorityKeyIdentifier', AuthorityKeyIdentifier],
    '2.5.29.14': ['subjectKeyIdentifier', SubjectKeyIdentifier],
    '2.5.29.31': ['crlDistributionPoints', CRLDistributionPoints],
    '2.5.29.46': ['freshestCRL', CRLDistributionPoints],
    '1.3.6.1.5.5.7.1.1': ['authorityInfoAccess', AuthorityInfoAccess],
    '1.3.6.1.5.5.7.1.11': ['subjectInfoAccess', AuthorityInfoAccess],
    '2.5.29.30': ['nameConstraints', NameConstraints],
}

describe('OpenSSL corpus: certificates', () => {
    for (const file of files('cert')) {
        const der = read('cert', file)
        describe(file, () => {
            register('cert', file, 'parse', () => {
                Certificate.fromDer(der)
            })
            register('cert', file, 'roundtrip', () => {
                expectRoundtrip(Certificate.fromDer(der), der)
            })
            register('cert', file, 'accessors', () => {
                const cert = Certificate.fromDer(der)
                cert.getCommonName()
                cert.getSubjectAltNamesAsStrings()
                cert.getSubjectPublicKeyInfo()
                cert.getIssuerSerial()
                cert.tbsCertificate.subject.toString()
            })
            register('cert', file, 'isSelfSigned', async () => {
                expect(await Certificate.fromDer(der).isSelfSigned()).toBe(true)
            })

            let cert: Certificate | undefined
            try {
                cert = Certificate.fromDer(der)
            } catch {
                return
            }
            for (const ext of cert.tbsCertificate.extensions ?? []) {
                const known = EXTENSIONS[ext.extnID.toString()]
                if (!known) continue
                const [name, cls] = known
                register('cert', file, `ext:${name}:parse`, () => {
                    ext.extnValue.parseAs(cls)
                })
                register('cert', file, `ext:${name}:roundtrip`, () => {
                    const parsed = ext.extnValue.parseAs(cls) as {
                        toDer(): Uint8Array
                    }
                    expect(hex(parsed.toDer())).toBe(hex(ext.extnValue.bytes))
                })
            }
        })
    }

    // Semantic checks driven by the file name
    for (const file of files('cert').filter((f) => f.startsWith('bc_'))) {
        const cA = !file.startsWith('bc_false')
        const pathLen = /pathlen(\d+)/.exec(file)?.[1]
        register('cert', file, 'basicConstraints:value', () => {
            const cert = Certificate.fromDer(read('cert', file))
            const bc = cert
                .getExtensionByOid('2.5.29.19')!
                .extnValue.parseAs(BasicConstraints)
            expect(bc.cA).toBe(cA)
            expect(bc.pathLenConstraint).toBe(
                pathLen === undefined ? undefined : Number(pathLen),
            )
        })
    }
    for (const file of files('cert').filter((f) => f.startsWith('serial_'))) {
        const raw = file.slice('serial_'.length, -'.der'.length)
        const expected = BigInt(raw.startsWith('0x') ? raw : Number(raw))
        register('cert', file, 'serialNumber:value', () => {
            const bytes = Certificate.fromDer(read('cert', file)).tbsCertificate
                .serialNumber.bytes
            const hexStr = hex(bytes)
            expect(BigInt('0x' + hexStr)).toBe(expected)
            // DER: minimal, and positive (a high first bit needs a 00 prefix)
            if (bytes.length > 1 && bytes[0] === 0) {
                expect(bytes[1] & 0x80).toBe(0x80)
            }
        })
    }
})

// ---------------------------------------------------------------------------
// CSRs, CRLs
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: certificate requests', () => {
    for (const file of files('csr')) {
        const der = read('csr', file)
        register('csr', file, 'parse', () => {
            CertificateRequest.fromDer(der)
        })
        register('csr', file, 'roundtrip', () => {
            expectRoundtrip(CertificateRequest.fromDer(der), der)
        })
    }
})

describe('OpenSSL corpus: CRLs', () => {
    for (const file of files('crl')) {
        const der = read('crl', file)
        register('crl', file, 'parse', () => {
            CertificateList.fromDer(der)
        })
        register('crl', file, 'roundtrip', () => {
            expectRoundtrip(CertificateList.fromDer(der), der)
        })
    }
})

// ---------------------------------------------------------------------------
// Keys
// ---------------------------------------------------------------------------
const keyClass = (file: string): any =>
    file.startsWith('pkcs8_')
        ? PrivateKeyInfo
        : file.startsWith('spki_')
          ? SubjectPublicKeyInfo
          : file.startsWith('rsaprivate')
            ? RSAPrivateKey
            : file.startsWith('rsapublic')
              ? RSAPublicKey
              : file.startsWith('ecprivate')
                ? ECPrivateKey
                : file.startsWith('ecdsa_sig')
                  ? ECDSASignature
                  : EncryptedPrivateKeyInfo

describe('OpenSSL corpus: keys and signatures', () => {
    for (const file of files('key')) {
        const der = read('key', file)
        const cls = keyClass(file)
        register('key', file, 'parse', () => {
            cls.fromDer(der)
        })
        register('key', file, 'roundtrip', () => {
            expectRoundtrip(cls.fromDer(der), der)
        })
    }
})

// ---------------------------------------------------------------------------
// CMS
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: CMS', () => {
    const rsaKey = () => PrivateKeyInfo.fromDer(read('key', 'pkcs8_rsa.der'))
    for (const file of files('cms')) {
        const der = read('cms', file)
        register('cms', file, 'contentInfo:parse', () => {
            ContentInfo.fromDer(der)
        })
        if (file.startsWith('sd_')) {
            register('cms', file, 'signedData:parse', () => {
                ContentInfo.fromDer(der).parseContentAs(SignedData)
            })
            if (!/_stream/.test(file)) {
                register('cms', file, 'signedData:roundtrip', () => {
                    const sd =
                        ContentInfo.fromDer(der).parseContentAs(SignedData)
                    expectRoundtrip(sd.toCms(), der)
                })
            }
            // certs-only bundles have no signers; nocerts has nothing to verify with
            if (!/certsonly|certs_crl|nocerts/.test(file)) {
                register('cms', file, 'signedData:verify', async () => {
                    const sd =
                        ContentInfo.fromDer(der).parseContentAs(SignedData)
                    const detached = sd.encapContentInfo.eContent === undefined
                    const result = await sd.verify(
                        detached
                            ? { data: new TextEncoder().encode(CMS_MESSAGE) }
                            : {},
                    )
                    expect(result.valid).toBe(true)
                })
            }
        } else if (file.startsWith('ed_') || file === 'authenveloped.der') {
            register('cms', file, 'envelopedData:parse', () => {
                ContentInfo.fromDer(der).parseContentAs(EnvelopedData)
            })
            register('cms', file, 'envelopedData:roundtrip', () => {
                const ed =
                    ContentInfo.fromDer(der).parseContentAs(EnvelopedData)
                expectRoundtrip(ed.toCms(), der)
            })
            if (/^ed_(rsa|stream|empty)/.test(file)) {
                register('cms', file, 'envelopedData:decrypt', async () => {
                    const ed =
                        ContentInfo.fromDer(der).parseContentAs(EnvelopedData)
                    const plain = await ed.decrypt(rsaKey())
                    if (file !== 'ed_stream.der' && file !== 'ed_empty.der') {
                        // OpenSSL canonicalises text content to CRLF unless -binary
                        expect(
                            new TextDecoder()
                                .decode(plain)
                                .replace(/\r\n/g, '\n'),
                        ).toBe(CMS_MESSAGE)
                    }
                })
            }
        }
    }
})

// ---------------------------------------------------------------------------
// PKCS#12
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: PKCS#12', () => {
    // [privateKeys, certificates]
    const expected: Record<string, [number, number]> = {
        'aes256_sha512.p12': [1, 1],
        'chain.p12': [1, 2],
        'default.p12': [1, 1],
        'ec.p12': [1, 1],
        'ed25519.p12': [1, 1],
        'iter1.p12': [1, 1],
        'keypbe_none.p12': [1, 1],
        'legacy_3des.p12': [1, 1],
        'localkeyid.p12': [1, 2],
        'nocerts.p12': [1, 0],
        'nokeys.p12': [0, 2],
        'nomac.p12': [1, 1],
        'nopass.p12': [1, 1],
    }
    for (const file of files('p12')) {
        const der = read('p12', file)
        register('p12', file, 'parse', () => {
            PFX.fromDer(der)
        })
        register('p12', file, 'roundtrip', () => {
            expectRoundtrip(PFX.fromDer(der), der)
        })
        register('p12', file, 'extractItems', async () => {
            const password = file === 'nopass.p12' ? '' : 'pw'
            const items = await PFX.fromDer(der).extractItems(password)
            expect([
                items.privateKeys.length,
                items.certificates.length,
            ]).toEqual(expected[file])
        })
    }
})

// ---------------------------------------------------------------------------
// OCSP
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: OCSP', () => {
    for (const file of files('ocsp')) {
        const der = read('ocsp', file)
        const isRequest = file.startsWith('req_')
        const cls: any = isRequest ? OCSPRequest : OCSPResponse
        register('ocsp', file, 'parse', () => {
            cls.fromDer(der)
        })
        register('ocsp', file, 'roundtrip', () => {
            expectRoundtrip(cls.fromDer(der), der)
        })
        if (
            !isRequest &&
            !/malformed|internal|try_later|sig_required|unauthorized/.test(file)
        ) {
            register('ocsp', file, 'basic:parse', () => {
                const response = OCSPResponse.fromDer(der)
                const basic = response.getBasicOCSPResponse()
                expect(hex(basic.toDer())).toBe(
                    hex(response.responseBytes!.response.bytes),
                )
            })
        }
    }
})
